var IM={nec:"data:image/jpeg;base64,",ear:"data:image/jpeg;base64,",rin:"data:image/jpeg;base64,",bra:"data:image/jpeg;base64,"};
var CUR="$",P=[["Aurelia Diamond Necklace","Necklaces",290,"nec"],["Solene Pendant Chain","Necklaces",210,"nec"],
["Velmora Drop Earrings","Earrings",260,"ear"],["Aria Diamond Studs","Earrings",180,"ear"],["Calla Twist Earrings","Earrings",230,"ear"],["Soleil Gold Hoops","Earrings",150,"ear"],
["Eternity Wave Ring","Rings",340,"rin"],["Orelle Band Ring","Rings",275,"rin"],["Vesper Solitaire","Rings",420,"rin"],["Mira Pavé Ring","Rings",310,"rin"],
["Wing Charm Bracelet","Bracelets",225,"bra"],["Fine Chain Bracelet","Bracelets",165,"bra"],["Opal Link Bracelet","Bracelets",205,"bra"],["Halo Tennis Bracelet","Bracelets",390,"bra"]].map(function(p,i){return{id:i,n:p[0],c:p[1],p:p[2],i:p[3]}});
var D={Necklaces:"Grace in every glance",Earrings:"Small details, big impact",Rings:"A symbol of forever",Bracelets:"Subtle yet stunning"};
var $=function(i){return document.getElementById(i)},fm=function(n){return CUR+n.toFixed(2)};
var cart=[];try{cart=JSON.parse(localStorage.getItem("vm2")||"[]")}catch(e){}
function save(){try{localStorage.setItem("vm2",JSON.stringify(cart))}catch(e){}}
var cat="All",ic=["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"],cn=["Necklaces","Earrings","Rings","Bracelets"];
$("cats").innerHTML=cn.map(function(c,k){return'<a class="c" href="#shop" onclick="go(\'shop\',\''+c+'\')"><img src="'+ic[k]+'" alt="">'+c+'</a>'}).join("")+'<div class="ex">Crafted with care<br>for your special moments.<a href="#shop" onclick="go(\'shop\')">Explore all &nbsp;<svg width="14" height="9"><use href="#ar"/></svg></a></div>';
$("fg").innerHTML=Object.keys(D).map(function(c){return'<a href="#shop" onclick="go(\'shop\',\''+c+'\')"><img src="'+IM[{Necklaces:"nec",Earrings:"ear",Rings:"rin",Bracelets:"bra"}[c]]+'" alt="'+c+'"><h3>'+c+'</h3><small>'+D[c]+'</small><svg width="14" height="9"><use href="#ar"/></svg></a>'}).join("");
function chips(){$("chips").innerHTML=["All"].concat(cn).map(function(c){return'<button class="'+(c==cat?"on":"")+'" onclick="cat=\''+c+'\';chips();list()">'+c+'</button>'}).join("")}
function list(){var s=$("q").value.toLowerCase(),o="";var r=P.filter(function(p){return(cat=="All"||p.c==cat)&&p.n.toLowerCase().indexOf(s)>-1});
if(o=="a")r.sort(function(a,b){return a.p-b.p});if(o=="d")r.sort(function(a,b){return b.p-a.p});if(o=="n")r.sort(function(a,b){return a.n.localeCompare(b.n)});
$("pg").innerHTML=r.length?r.map(function(p){return'<article class="pc"><img src="'+IM[p.i]+'" alt="'+p.n+'" onclick="view('+p.id+')"><h3 onclick="view('+p.id+')">'+p.n+'</h3><div class="pr">'+fm(p.p)+'</div><button class="btn sm" onclick="add('+p.id+')">Add to bag</button></article>'}).join(""):'<div class="empty">No pieces match your search. Try another name or category.</div>'}
function go(v,c){$("home").style.display=v=="shop"?"none":"";$("shop").style.display=v=="shop"?"block":"none";if(v=="shop"){cat=c||"All";chips();$("q").value="";list()}
document.querySelectorAll("nav a[data-v]").forEach(function(a){a.classList.toggle("on",a.dataset.v==v)});$("nav").classList.remove("on");if(v=="shop")scrollTo({top:0});try{history.replaceState(null,"","#"+v)}catch(e){}}
addEventListener("hashchange",function(){var h=location.hash.slice(1);if(h=="shop"||h=="home")go(h)});
$("q").oninput=list;
function toast(m){var t=$("ts");t.textContent=m;t.classList.add("on");clearTimeout(t.x);t.x=setTimeout(function(){t.classList.remove("on")},2200)}
function add(id,n){var f=cart.find(function(x){return x.id==id});f?f.q+=n||1:cart.push({id:id,q:n||1});save();upd();toast("Added to your bag")}
function upd(){var c=0,t=0;cart.forEach(function(x){c+=x.q;t+=x.q*P[x.id].p});$("cc").textContent=c;$("tt").textContent=fm(t);
$("cl").innerHTML=cart.length?cart.map(function(x){var p=P[x.id];return'<div class="ci"><img src="'+IM[p.i]+'" alt=""><div><h3>'+p.n+'</h3>'+fm(p.p)+'<br><span class="q"><button onclick="chg('+x.id+',-1)" aria-label="Less">−</button><span>'+x.q+'</span><button onclick="chg('+x.id+',1)" aria-label="More">+</button></span></div><button onclick="chg('+x.id+',-99)" aria-label="Remove">✕</button></div>'}).join(""):'<p style="color:var(--mut);padding:30px 0">Your bag is empty. Browse the shop to find your next piece.</p>'}
function chg(id,d){var f=cart.find(function(x){return x.id==id});f.q+=d;if(f.q<1)cart=cart.filter(function(x){return x.id!=id});save();upd()}
function closeAll(){["ov","dr","md"].forEach(function(i){$(i).classList.remove("on")})}
function openCart(){$("ov").classList.add("on");$("dr").classList.add("on")}
function view(id){var p=P[id];$("md").innerHTML='<div class="mh"><span class="eyebrow">'+p.c+'</span><button onclick="closeAll()" aria-label="Close">✕</button></div><div class="pd"><img src="'+IM[p.i]+'" alt="'+p.n+'"><div><h2 style="font-size:26px">'+p.n+'</h2><div style="margin-top:6px">'+fm(p.p)+'</div><p>'+D[p.c==="Pendants"?"Necklaces":p.c]+'. Handcrafted in 18k gold-plated sterling silver with ethically sourced stones. Free shipping and 30-day returns.</p><button class="btn" onclick="add('+id+');closeAll();openCart()">Add to bag</button></div></div>';$("ov").classList.add("on");$("md").classList.add("on")}
function checkout(){if(!cart.length)return toast("Your bag is empty");closeAll();$("md").innerHTML='<div class="mh"><h2 style="font-size:24px">Checkout</h2><button onclick="closeAll()" aria-label="Close">✕</button></div><form class="fm" onsubmit="done(event)"><input required placeholder="Full name"><input required type="email" placeholder="Email"><input required type="tel" placeholder="Phone"><input required placeholder="Address"><input required placeholder="City"><select><option>Cash on delivery</option><option>Card payment</option></select><div class="tot"><span>Total</span><span>'+$("tt").textContent+'</span></div><button class="btn" style="justify-content:center">Place order</button></form>';$("ov").classList.add("on");$("md").classList.add("on")}
function done(e){e.preventDefault();cart=[];save();upd();$("md").innerHTML='<div class="mh"><h2 style="font-size:24px">Thank you</h2><button onclick="closeAll()" aria-label="Close">✕</button></div><p style="line-height:1.7;color:var(--mut)">Your order is confirmed. We will email you the details shortly.</p>'}
addEventListener("keydown",function(e){if(e.key=="Escape")closeAll()});
var MOON='<path d="M14.5 10.2A6.2 6.2 0 0 1 6.8 2.5a6.2 6.2 0 1 0 7.7 7.7z"/>',SUN='<circle cx="8.5" cy="8.5" r="3"/><path d="M8.5 1v2M8.5 14v2M1 8.5h2M14 8.5h2M3.2 3.2l1.4 1.4M12.4 12.4l1.4 1.4M3.2 13.8l1.4-1.4M12.4 4.6l1.4-1.4"/>';
chips();list();upd();if(location.hash=="#shop")go("shop");